/**
 * Streams the issue CSV; requires the `csv_export` flag.
 *
 * Owner D. Query parameters are parsed with `exportIssuesSchema` — the same
 * schema the export UI submits — so `?includeArchived=true` cannot mean one
 * thing in the form and another here.
 *
 * Must call (do not reimplement): can, isEnabled, toCsv
 */

import { PENDING_ISSUE_ID, PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { csvResponseHeaders, toCsv } from "@/lib/csv";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { exportIssuesSchema } from "@/schemas/export";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { listIssues } from "@/server/services/issue-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { Issue } from "@/types/issue";

export const dynamic = "force-dynamic";

const EXPORT_PAGE_LIMIT = 100;

const COLUMNS: readonly string[] = [
  "number",
  "title",
  "status",
  "priority",
  "assigneeId",
  "authorId",
  "dueAt",
  "createdAt",
  "updatedAt",
];

export async function GET(request: Request): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    const actor = await getActor(orgSlug);
    const { organization } = await getOrganizationSummary(actor, actor.orgId);

    if (!isEnabled("csv_export", buildFlagContext(actor, organization))) {
      return failure("forbidden", "CSV export is not included in this plan.");
    }

    const allowed = can(actor, "issue:read", {
      kind: "issue",
      orgId: actor.orgId,
      projectId: PENDING_PROJECT_ID,
      issueId: PENDING_ISSUE_ID,
      authorId: actor.userId,
      assigneeId: actor.userId,
    });
    if (!allowed) {
      return failure("forbidden", "You cannot export issues in this organization.");
    }

    const parsed = exportIssuesSchema.safeParse({
      orgId: actor.orgId,
      projectId: url.searchParams.get("projectId") ?? undefined,
      includeArchived: url.searchParams.get("includeArchived") ?? false,
      format: url.searchParams.get("format") ?? "csv",
    });
    if (!parsed.success) {
      return failure("validation_failed", "Bad export parameters.");
    }

    const page = await listIssues(actor, {
      orgId: parsed.data.orgId,
      projectId: parsed.data.projectId,
      includeArchived: parsed.data.includeArchived,
      limit: EXPORT_PAGE_LIMIT,
    });

    if (parsed.data.format === "json") {
      return Response.json({ items: page.items, total: page.total });
    }

    const csv = toCsv(page.items.map(toRow), COLUMNS);
    return new Response(csv, {
      headers: csvResponseHeaders(`taskflow-issues-${organization.slug}.csv`),
    });
  } catch (error) {
    return errorResponse(error);
  }
}

/** Flattens an `Issue` into the scalar row shape `toCsv` accepts. */
function toRow(issue: Issue): Record<string, string | number | boolean | null> {
  return {
    number: issue.number,
    title: issue.title,
    status: issue.status,
    priority: issue.priority,
    assigneeId: issue.assigneeId,
    authorId: issue.authorId,
    dueAt: issue.dueAt,
    createdAt: issue.createdAt,
    updatedAt: issue.updatedAt,
  };
}

/**
 * Cross-project "my issues" view.
 *
 * Owner D. Unlike the per-project list this one spans the whole organization,
 * so the repository filter carries no `projectId` — only the org scope the
 * actor already implies.
 *
 * Must call (do not reimplement): can
 */

import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { IssueList } from "@/components/domain/issue/issue-list";
import { EmptyState } from "@/components/ui/empty-state";
import { can } from "@/lib/permissions";
import { PENDING_ISSUE_ID, PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { searchParamsPaginationSchema } from "@/schemas/pagination";
import { getIssue, listIssues } from "@/server/services/issue-service";
import { ISSUE_STATUSES, type IssueStatus, type IssueWithRelations } from "@/types/issue";
import { loadTenantContext } from "../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "My issues",
};

const OPEN_STATUSES: readonly IssueStatus[] = [
  "backlog",
  "todo",
  "in_progress",
  "in_review",
];

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const allowed = can(actor, "issue:read", {
    kind: "issue",
    orgId: org.id,
    projectId: PENDING_PROJECT_ID,
    issueId: PENDING_ISSUE_ID,
    authorId: actor.userId,
    assigneeId: actor.userId,
  });
  if (!allowed) {
    notFound();
  }

  const pagination = searchParamsPaginationSchema.parse(search);
  const status = parseStatuses(search.status);

  const page = await listIssues(actor, {
    orgId: org.id,
    assigneeId: actor.userId,
    status: [...status],
    limit: pagination.perPage,
    cursor: pagination.cursor ?? null,
  });

  // `IssueList` wants the relations bundle; fetching them one by one is fine at
  // page size, and keeps the list query itself cheap.
  const rows: IssueWithRelations[] = await Promise.all(
    page.items.map((issue) => getIssue(actor, org.id, issue.id)),
  );

  return (
    <div className="space-y-8">
      <header>
        <h1 className="text-2xl font-semibold tracking-tight">My issues</h1>
        <p className="mt-1 text-sm text-slate-600">
          Issues assigned to you across every project in {org.name}.
        </p>
      </header>

      {rows.length === 0 ? (
        <EmptyState
          title="No issues assigned to you"
          description="When somebody assigns you an issue it lands here."
        />
      ) : (
        <IssueList issues={rows} actor={actor} />
      )}
    </div>
  );
}

/** `?status=todo&status=in_progress` narrows the list; anything else is open. */
function parseStatuses(
  raw: string | string[] | undefined,
): readonly IssueStatus[] {
  const values = Array.isArray(raw) ? raw : raw === undefined ? [] : [raw];
  const known = values.filter((value): value is IssueStatus =>
    (ISSUE_STATUSES as readonly string[]).includes(value),
  );
  return known.length > 0 ? known : OPEN_STATUSES;
}

/**
 * Issue business rules: authorization, per-project issue quota, numbering, status transitions and the events every other concern reacts to.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, assertNotArchived
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import {
  actorEnvelope,
  issueResource,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  AssignIssueInput,
  ChangeIssueStatusInput,
  CreateIssueInput,
  IssueFilterInput,
  MoveIssueInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type { IssueId, OrgId, Page, ProjectId } from "@/types/common";
import type { Issue, IssueBoardColumn, IssueWithRelations } from "@/types/issue";
import type { Actor } from "@/types/member";

/**
 * Creates an issue after four gates: tenant scope, the `issue:create`
 * permission, a live parent project and the plan's per-project issue quota.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

  return issue;
}

export async function updateIssue(
  actor: Actor,
  input: UpdateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.updateIssue(input);

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: Object.keys(input).filter(
      (key) => key !== "orgId" && key !== "issueId",
    ),
  });

  return after;
}

/** Status transitions are an `issue:update`, not a separate permission. */
export async function changeIssueStatus(
  actor: Actor,
  input: ChangeIssueStatusInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.status === input.status) return before;

  const after = await issueRepo.setIssueStatus(
    input.orgId,
    input.issueId,
    input.status,
  );

  await emit("issue.status_changed", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    from: before.status,
    to: after.status,
  });

  return after;
}

/**
 * Assignment has its own permission because a member may reassign work they
 * do not otherwise own. Un-assigning publishes `issue.updated` instead, since
 * `issue.assigned` carries a non-null assignee by contract.
 */
export async function assignIssue(
  actor: Actor,
  input: AssignIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:assign", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.setIssueAssignee(
    input.orgId,
    input.issueId,
    input.assigneeId,
  );

  if (input.assigneeId === null) {
    await emit("issue.updated", {
      ...actorEnvelope(actor),
      issueId: after.id,
      projectId: after.projectId,
      changedFields: ["assigneeId"],
    });
    return after;
  }

  await emit("issue.assigned", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    previousAssigneeId: before.assigneeId,
    assigneeId: input.assigneeId,
  });

  return after;
}

export async function archiveIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const archived = await issueRepo.archiveIssue(orgId, issueId);

  await emit("issue.archived", {
    ...actorEnvelope(actor),
    issueId: archived.id,
    projectId: archived.projectId,
  });

  return archived;
}

/**
 * Board drag-and-drop. The index is presentation-only — the board renders by
 * `updated_at` — so a move is a status change plus a touch.
 */
export async function moveIssue(
  actor: Actor,
  input: MoveIssueInput,
): Promise<Issue> {
  return changeIssueStatus(actor, {
    orgId: input.orgId,
    issueId: input.issueId,
    status: input.toStatus,
  });
}

export async function getIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueWithRelations> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const labels = await labelRepo.listLabelsForIssues(orgId, [issue.id]);

  return {
    issue,
    labels: labels[issue.id] ?? [],
    commentCount: await commentRepo.countComments(orgId, issue.id),
    attachmentCount: (await attachmentRepo.listAttachments(orgId, issue.id))
      .length,
  };
}

export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  // A cross-project list is an org-wide read; per-project visibility is
  // enforced when the caller opens an individual issue.
  assertCan(actor, "issue:read", orgResource(input.orgId));
  return issueRepo.listIssues(input);
}

export async function getBoard(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueBoardColumn[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "issue:read", projectResource(project));

  return issueRepo.listBoardColumns(orgId, projectId);
}

import { z } from "zod";
import type { IssuePriority, IssueStatus } from "@/types/issue";
import {
  archiveScopeSchema,
  isoTimestampSchema,
  issueIdSchema,
  labelIdSchema,
  orgIdSchema,
  pageRequestSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";

export const issueStatusSchema = z.enum([
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
]);

export const issuePrioritySchema = z.enum([
  "none",
  "low",
  "medium",
  "high",
  "urgent",
]);

export const createIssueSchema = z.object({
  orgId: orgIdSchema,
  projectId: projectIdSchema,
  title: z.string().min(3, "give the issue a title").max(200),
  description: z.string().max(20_000).nullable().default(null),
  status: issueStatusSchema.default("backlog"),
  priority: issuePrioritySchema.default("none"),
  assigneeId: userIdSchema.nullable().default(null),
  parentId: issueIdSchema.nullable().default(null),
  estimate: z.number().int().min(0).max(100).nullable().default(null),
  dueAt: isoTimestampSchema.nullable().default(null),
  labelIds: z.array(labelIdSchema).max(20).default([]),
});

export const updateIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  title: z.string().min(3).max(200).optional(),
  description: z.string().max(20_000).nullable().optional(),
  priority: issuePrioritySchema.optional(),
  estimate: z.number().int().min(0).max(100).nullable().optional(),
  dueAt: isoTimestampSchema.nullable().optional(),
  labelIds: z.array(labelIdSchema).max(20).optional(),
});

export const changeIssueStatusSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  status: issueStatusSchema,
});

export const assignIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  assigneeId: userIdSchema.nullable(),
});

export const archiveIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
});

export const issueFilterSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema.optional(),
    status: z.array(issueStatusSchema).optional(),
    priority: z.array(issuePrioritySchema).optional(),
    assigneeId: userIdSchema.nullable().optional(),
    authorId: userIdSchema.optional(),
    labelIds: z.array(labelIdSchema).optional(),
    query: z.string().max(200).optional(),
    dueBefore: isoTimestampSchema.optional(),
  })
  .extend(pageRequestSchema.shape)
  .extend(archiveScopeSchema.shape);

/** Board drag-and-drop payload: move one issue into a column at an index. */
export const moveIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  toStatus: issueStatusSchema,
  toIndex: z.number().int().min(0),
});

const _statusParity: IssueStatus = "in_review" satisfies z.infer<
  typeof issueStatusSchema
>;
const _priorityParity: IssuePriority = "urgent" satisfies z.infer<
  typeof issuePrioritySchema
>;
void _statusParity;
void _priorityParity;

export type CreateIssueInput = z.infer<typeof createIssueSchema>;
export type UpdateIssueInput = z.infer<typeof updateIssueSchema>;
export type ChangeIssueStatusInput = z.infer<typeof changeIssueStatusSchema>;
export type AssignIssueInput = z.infer<typeof assignIssueSchema>;
export type IssueFilterInput = z.infer<typeof issueFilterSchema>;
export type MoveIssueInput = z.infer<typeof moveIssueSchema>;

/**
 * The URL is the single source of truth for the issue list filter: a filtered
 * view has to be shareable and survive a reload, and the server component that
 * renders the page parses the very same query string. These two functions are
 * that codec, kept pure so both sides can use them.
 *
 * `assignee=none` is the sanctioned spelling of "unassigned" — `undefined`
 * means "don't filter on assignee at all", which is a different query.
 */
import type { LabelId, ProjectId, IsoTimestamp, UserId } from "@/types/common";
import {
  ISSUE_PRIORITIES,
  ISSUE_STATUSES,
  type IssueFilter,
  type IssuePriority,
  type IssueStatus,
} from "@/types/issue";

export const UNASSIGNED_TOKEN = "none";

export interface ReadableParams {
  get(name: string): string | null;
}

function splitList(raw: string | null): readonly string[] {
  if (raw === null || raw.length === 0) return [];
  return raw
    .split(",")
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
}

export function parseIssueFilterParams(params: ReadableParams): IssueFilter {
  const statuses = splitList(params.get("status")).filter(
    (value): value is IssueStatus =>
      ISSUE_STATUSES.includes(value as IssueStatus),
  );
  const priorities = splitList(params.get("priority")).filter(
    (value): value is IssuePriority =>
      ISSUE_PRIORITIES.includes(value as IssuePriority),
  );
  const labelIds = splitList(params.get("label")) as readonly LabelId[];
  const project = params.get("project");
  const assignee = params.get("assignee");
  const author = params.get("author");
  const query = params.get("q");
  const dueBefore = params.get("due_before");

  const filter: IssueFilter = {
    ...(project !== null ? { projectId: project as ProjectId } : {}),
    ...(statuses.length > 0 ? { status: statuses } : {}),
    ...(priorities.length > 0 ? { priority: priorities } : {}),
    ...(assignee !== null
      ? {
          assigneeId:
            assignee === UNASSIGNED_TOKEN ? null : (assignee as UserId),
        }
      : {}),
    ...(author !== null ? { authorId: author as UserId } : {}),
    ...(labelIds.length > 0 ? { labelIds } : {}),
    ...(query !== null && query.length > 0 ? { query } : {}),
    ...(dueBefore !== null ? { dueBefore: dueBefore as IsoTimestamp } : {}),
    ...(params.get("archived") === "1" ? { includeArchived: true } : {}),
  };

  return filter;
}

/** Inverse of `parseIssueFilterParams`; omits every empty dimension so the
 *  canonical URL for "no filter" is the bare path. */
export function issueFilterToParams(
  filter: IssueFilter,
): Readonly<Record<string, string>> {
  const params: Record<string, string> = {};
  if (filter.projectId !== undefined) params.project = filter.projectId;
  if (filter.status !== undefined && filter.status.length > 0) {
    params.status = filter.status.join(",");
  }
  if (filter.priority !== undefined && filter.priority.length > 0) {
    params.priority = filter.priority.join(",");
  }
  if (filter.assigneeId !== undefined) {
    params.assignee = filter.assigneeId ?? UNASSIGNED_TOKEN;
  }
  if (filter.authorId !== undefined) params.author = filter.authorId;
  if (filter.labelIds !== undefined && filter.labelIds.length > 0) {
    params.label = filter.labelIds.join(",");
  }
  if (filter.query !== undefined && filter.query.length > 0) {
    params.q = filter.query;
  }
  if (filter.dueBefore !== undefined) params.due_before = filter.dueBefore;
  if (filter.includeArchived === true) params.archived = "1";
  return params;
}

/** How many dimensions the user has narrowed on, for the "clear" affordance. */
export function activeFilterCount(filter: IssueFilter): number {
  return Object.keys(issueFilterToParams(filter)).length;
}

export function issueFilterQueryString(filter: IssueFilter): string {
  const search = new URLSearchParams(issueFilterToParams(filter));
  const serialised = search.toString();
  return serialised.length > 0 ? `?${serialised}` : "";
}

/**
 * Issue rows: the widest query surface in the app. Every method takes `orgId` first and honours `IssueFilter.includeArchived`.
 *
 * Must call (do not reimplement): archivePatch, restorePatch, shouldFilterArchived
 */
import {
  and,
  count,
  desc,
  eq,
  inArray,
  isNotNull,
  isNull,
  like,
  lt,
  or,
  sql,
} from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  archivePatch,
  restorePatch,
  shouldFilterArchived,
} from "@/lib/soft-delete";
import { attachments, comments, getDb, issueLabels, issues } from "@/server/db";
import { ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toIssue } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type {
  CreateIssueInput,
  IssueFilterInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type {
  ArchiveScope,
  IsoTimestamp,
  IssueId,
  LabelId,
  OrgId,
  Page,
  ProjectId,
  UserId,
} from "@/types/common";
import type {
  Issue,
  IssueBoardColumn,
  IssueStatus,
  IssueWithRelations,
} from "@/types/issue";
import type { SQL } from "drizzle-orm";

/** Statuses whose entry stamps `completed_at`; leaving one clears it again. */
const TERMINAL_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

export async function findIssueById(
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue | null> {
  const row = getDb()
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();
  if (!row) return null;

  const labels = await listLabelsForIssues(orgId, [row.id as IssueId]);
  return toIssue(row, (labels[row.id] ?? []).map((label) => label.id));
}

export async function findIssueByNumber(
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): Promise<Issue | null> {
  const row = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        eq(issues.number, issueNumber),
      ),
    )
    .get();
  return row ? toIssue(row) : null;
}

/** Builds the shared predicate list behind `listIssues` and its count. */
function issueFilters(input: IssueFilterInput): readonly SQL[] {
  const scope: ArchiveScope = shouldFilterArchived(input)
    ? {}
    : { includeArchived: true };

  return compact(
    orgPredicate(issues.orgId, input.orgId),
    livePredicate(issues.archivedAt, scope),
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    input.status === undefined || input.status.length === 0
      ? undefined
      : inArray(issues.status, [...input.status]),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    // `null` and `undefined` both arrive from the "Anyone" option of the
    // filter bar, so neither narrows the list.
    input.assigneeId ? eq(issues.assigneeId, input.assigneeId) : undefined,
    input.authorId === undefined
      ? undefined
      : eq(issues.authorId, input.authorId),
    input.dueBefore === undefined ? undefined : lt(issues.dueAt, input.dueBefore),
    input.query === undefined
      ? undefined
      : or(
          like(issues.title, `%${input.query}%`),
          like(issues.description, `%${input.query}%`),
        ),
    input.labelIds === undefined || input.labelIds.length === 0
      ? undefined
      : inArray(
          issues.id,
          getDb()
            .select({ id: issueLabels.issueId })
            .from(issueLabels)
            .where(
              and(
                orgPredicate(issueLabels.orgId, input.orgId),
                inArray(issueLabels.labelId, [...input.labelIds]),
              ),
            ),
        ),
  );
}

export async function listIssues(
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  const db = getDb();
  const filters = issueFilters(input);
  const sort = { sortColumn: issues.createdAt, idColumn: issues.id };

  const total = db
    .select({ value: count() })
    .from(issues)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(issues)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(issues.createdAt), desc(issues.id))
    .limit(probeLimit(input.limit))
    .all();

  const labels = await listLabelsForIssues(
    input.orgId,
    rows.map((row) => row.id as IssueId),
  );

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
    (row) => ({ id: row.id, sortValue: row.createdAt }),
  );
}

/**
 * The list view needs comment and attachment counts per row. Two grouped
 * queries beat N+1 round trips, so the counts are folded in afterwards.
 */
export async function listIssuesWithRelations(
  input: IssueFilterInput,
): Promise<Page<IssueWithRelations>> {
  const db = getDb();
  const page = await listIssues(input);
  const ids = page.items.map((issue) => issue.id);
  if (ids.length === 0) {
    return { items: [], nextCursor: page.nextCursor, total: page.total };
  }

  const commentCounts = db
    .select({ issueId: comments.issueId, value: count() })
    .from(comments)
    .where(
      and(
        orgPredicate(comments.orgId, input.orgId),
        inArray(comments.issueId, [...ids]),
        isNull(comments.archivedAt),
      ),
    )
    .groupBy(comments.issueId)
    .all();

  const attachmentCounts = db
    .select({ issueId: attachments.issueId, value: count() })
    .from(attachments)
    .where(
      and(
        orgPredicate(attachments.orgId, input.orgId),
        inArray(attachments.issueId, [...ids]),
      ),
    )
    .groupBy(attachments.issueId)
    .all();

  const labels = await listLabelsForIssues(input.orgId, ids);
  const commentsBy = new Map(commentCounts.map((r) => [r.issueId, r.value]));
  const attachmentsBy = new Map(
    attachmentCounts.map((r) => [r.issueId, r.value]),
  );

  return {
    items: page.items.map((issue) => ({
      issue,
      labels: labels[issue.id] ?? [],
      commentCount: commentsBy.get(issue.id) ?? 0,
      attachmentCount: attachmentsBy.get(issue.id) ?? 0,
    })),
    nextCursor: page.nextCursor,
    total: page.total,
  };
}

/** One column per status, in `ISSUE_STATUSES` order, live rows only. */
export async function listBoardColumns(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueBoardColumn[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(desc(issues.updatedAt))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );

  return ISSUE_STATUSES.map((status) => {
    const column = rows
      .filter((row) => row.status === status)
      .map((row) => toIssue(row, (labels[row.id] ?? []).map((l) => l.id)));
    return { status, issues: column, total: column.length };
  });
}

export async function countIssues(
  orgId: OrgId,
  projectId: ProjectId,
  scope: ArchiveScope = {},
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, scope),
        ),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  return (row?.value ?? 0) + 1;
}

export async function insertIssue(
  input: CreateIssueInput,
  authorId: UserId,
  issueNumber: number,
): Promise<Issue> {
  const stamp = toIsoTimestamp(new Date());
  const db = getDb();

  const row = db
    .insert(issues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      number: issueNumber,
      title: input.title,
      description: input.description,
      status: input.status,
      priority: input.priority,
      authorId,
      assigneeId: input.assigneeId,
      parentId: input.parentId,
      estimate: input.estimate,
      dueAt: input.dueAt,
      startedAt: null,
      completedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  if (input.labelIds.length > 0) {
    db.insert(issueLabels)
      .values(
        input.labelIds.map((labelId) => ({
          orgId: input.orgId,
          issueId: row.id,
          labelId,
        })),
      )
      .run();
  }

  return toIssue(row, input.labelIds);
}

export async function updateIssue(input: UpdateIssueInput): Promise<Issue> {
  const db = getDb();
  const row = db
    .update(issues)
    .set({
      ...(input.title === undefined ? {} : { title: input.title }),
      ...(input.description === undefined
        ? {}
        : { description: input.description }),
      ...(input.priority === undefined ? {} : { priority: input.priority }),
      ...(input.estimate === undefined ? {} : { estimate: input.estimate }),
      ...(input.dueAt === undefined ? {} : { dueAt: input.dueAt }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(issues.orgId, input.orgId),
        eq(issues.id, input.issueId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${input.issueId} not found`);

  if (input.labelIds !== undefined) {
    db.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, input.orgId),
          eq(issueLabels.issueId, input.issueId),
        ),
      )
      .run();
    if (input.labelIds.length > 0) {
      db.insert(issueLabels)
        .values(
          input.labelIds.map((labelId: LabelId) => ({
            orgId: input.orgId,
            issueId: input.issueId,
            labelId,
          })),
        )
        .run();
    }
  }

  const labels = await listLabelsForIssues(input.orgId, [input.issueId]);
  return toIssue(row, (labels[input.issueId] ?? []).map((label) => label.id));
}

/** Status transitions maintain `started_at` / `completed_at` bookkeeping. */
export async function setIssueStatus(
  orgId: OrgId,
  issueId: IssueId,
  status: IssueStatus,
): Promise<Issue> {
  const stamp = toIsoTimestamp(new Date());
  const current = getDb()
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();

  if (!current) throw new Error(`Issue ${issueId} not found`);

  const row = getDb()
    .update(issues)
    .set({
      status,
      startedAt:
        status === "in_progress" && current.startedAt === null
          ? stamp
          : current.startedAt,
      completedAt: TERMINAL_STATUSES.includes(status) ? stamp : null,
      updatedAt: stamp,
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  return toIssue(row);
}

export async function setIssueAssignee(
  orgId: OrgId,
  issueId: IssueId,
  assigneeId: UserId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ assigneeId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

export async function archiveIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set(archivePatch())
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

export async function restoreIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set(restorePatch())
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

/** Cascade behind `ProjectService.archiveProject`; returns the row count. */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

/** Live, still-open issues whose due date has passed. Drives the overdue job. */
export async function listOverdueIssues(
  orgId: OrgId,
  now: IsoTimestamp,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          livePredicate(issues.archivedAt, {}),
          isNotNull(issues.dueAt),
          lt(issues.dueAt, now),
          inArray(issues.status, ["backlog", "todo", "in_progress", "in_review"]),
        ),
      ),
    )
    .orderBy(issues.dueAt)
    .all();

  return rows.map((row) => toIssue(row));
}

"use client";

/**
 * Reads and writes the issue filter through the URL search params.
 */
import { useCallback, useMemo } from "react";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import type { IssueFilter } from "@/types/issue";
import {
  issueFilterQueryString,
  parseIssueFilterParams,
} from "./issue-filter-params";

export function useIssueFilters(): {
  filter: IssueFilter;
  setFilter: (filter: IssueFilter) => void;
  reset: () => void;
} {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const filter = useMemo(
    () => parseIssueFilterParams(searchParams),
    [searchParams],
  );

  const setFilter = useCallback(
    (next: IssueFilter) => {
      // Changing a filter always returns to page 1; keeping the old cursor
      // would show an empty page for a narrower result set.
      router.replace(`${pathname}${issueFilterQueryString(next)}`, {
        scroll: false,
      });
    },
    [router, pathname],
  );

  const reset = useCallback(() => {
    router.replace(pathname, { scroll: false });
  }, [router, pathname]);

  return { filter, setFilter, reset };
}

"use client";

/**
 * Role-aware sidebar: every item is filtered through `can()` and its flag.
 *
 * Must call (do not reimplement): can, isEnabled
 */
import Link from "next/link";
import { SETTINGS_NAV, SIDEBAR_NAV, visibleNav, type NavItem } from "@/config/nav";
import { cn } from "@/lib/cn";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { orgPath, projectPath } from "@/lib/url";
import { orgFlagContext } from "@/hooks/flag-context";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";
import type { ReactElement } from "react";
import { organizationResource } from "../permission/resources";
import { OrgSwitcher } from "./org-switcher";

export type AppSidebarProps = {
  org: Organization;
  actor: Actor;
  flags: FeatureFlagSnapshot;
  projects: readonly Project[];
  pathname: string;
  /** Orgs offered by the switcher; defaults to just the current one. */
  organizations?: readonly Organization[];
};

/** True when `pathname` is the item's route or lives beneath it. */
export function isActiveSegment(pathname: string, href: string): boolean {
  return pathname === href || pathname.startsWith(`${href}/`);
}

export function AppSidebar(props: AppSidebarProps): ReactElement | null {
  const { org, actor, flags, projects, pathname, organizations } = props;

  // The nav tree declares the permission and flag each item needs; `visibleNav`
  // applies both. Nothing here branches on `actor.role`.
  const context = orgFlagContext(org, actor);
  const primary = visibleNav(SIDEBAR_NAV, actor, flags);
  const settings = visibleNav(SETTINGS_NAV, actor, flags);

  // The project shortcut list is its own gate: reading projects at all, and
  // the public-projects flag for the "shared" affordance.
  const mayReadProjects = can(
    actor,
    "project:read",
    organizationResource(org.id),
  );
  const publicProjectsOn =
    flags.public_projects === true || isEnabled("public_projects", context);

  function renderItem(item: NavItem): ReactElement {
    const href = orgPath(org.slug, item.segment);
    return (
      <li key={item.key}>
        <Link
          href={href}
          className={cn(
            "block rounded px-2 py-1 text-sm",
            isActiveSegment(pathname, href)
              ? "bg-neutral-200 font-medium"
              : "hover:bg-neutral-100",
          )}
        >
          {item.label}
        </Link>
        {item.children !== undefined && item.children.length > 0 ? (
          <ul className="ml-3 mt-0.5 space-y-0.5">
            {item.children.map(renderItem)}
          </ul>
        ) : null}
      </li>
    );
  }

  return (
    <nav className="app-sidebar flex w-56 shrink-0 flex-col gap-4 border-r p-3">
      <OrgSwitcher
        organizations={organizations ?? [org]}
        currentSlug={org.slug}
      />

      <ul className="space-y-0.5">{primary.map(renderItem)}</ul>

      {mayReadProjects && projects.length > 0 ? (
        <section>
          <h2 className="px-2 text-xs font-medium uppercase text-neutral-500">
            Projects
          </h2>
          <ul className="mt-1 space-y-0.5">
            {projects.map((project) => {
              const href = projectPath(org.slug, project.slug);
              return (
                <li key={project.id}>
                  <Link
                    href={href}
                    className={cn(
                      "flex items-center justify-between rounded px-2 py-1 text-sm",
                      isActiveSegment(pathname, href)
                        ? "bg-neutral-200 font-medium"
                        : "hover:bg-neutral-100",
                    )}
                  >
                    <span className="truncate">{project.name}</span>
                    {publicProjectsOn && project.visibility === "public" ? (
                      <span className="text-xs text-neutral-500">public</span>
                    ) : null}
                  </Link>
                </li>
              );
            })}
          </ul>
        </section>
      ) : null}

      {settings.length > 0 ? (
        <section className="mt-auto">
          <h2 className="px-2 text-xs font-medium uppercase text-neutral-500">
            Settings
          </h2>
          <ul className="mt-1 space-y-0.5">{settings.map(renderItem)}</ul>
        </section>
      ) : null}
    </nav>
  );
}

"use client";

/**
 * Filter chips writing back into the URL search params.
 */
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, type SelectOption } from "@/components/ui/select";
import { humanizeStatus } from "@/lib/format";
import { activeFilterCount, UNASSIGNED_TOKEN } from "@/hooks/issue-filter-params";
import { ISSUE_STATUSES, type IssueFilter, type IssueStatus } from "@/types/issue";
import type { UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";
import type { Project } from "@/types/project";
import type { ProjectId } from "@/types/common";
import type { ReactElement } from "react";

export type IssueFilterBarProps = {
  filter: IssueFilter;
  projects: readonly Project[];
  members: readonly MemberWithUser[];
  onChange: (filter: IssueFilter) => void;
};

/** Adds or removes one status without disturbing the other dimensions. */
export function toggleStatus(
  filter: IssueFilter,
  status: IssueStatus,
): IssueFilter {
  const current = filter.status ?? [];
  const next = current.includes(status)
    ? current.filter((value) => value !== status)
    : [...current, status];
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

export function IssueFilterBar(
  props: IssueFilterBarProps,
): ReactElement | null {
  const { filter, projects, members, onChange } = props;

  const projectOptions: readonly SelectOption[] = [
    { value: "", label: "All projects" },
    ...projects.map((project) => ({
      value: project.id,
      label: project.name,
    })),
  ];

  const assigneeOptions: readonly SelectOption[] = [
    { value: "", label: "Anyone" },
    { value: UNASSIGNED_TOKEN, label: "Unassigned" },
    ...members.map((member) => ({
      value: member.userId,
      label: member.user.name,
    })),
  ];

  return (
    <div className="flex flex-wrap items-center gap-2">
      <Input
        name="q"
        type="search"
        value={filter.query ?? ""}
        placeholder="Search issues"
        onChange={(value) =>
          onChange(value.length === 0 ? stripQuery(filter) : { ...filter, query: value })
        }
      />

      <Select
        name="project"
        value={filter.projectId ?? ""}
        options={projectOptions}
        onChange={(value) =>
          onChange(
            value.length === 0
              ? stripProject(filter)
              : { ...filter, projectId: value as ProjectId },
          )
        }
      />

      <Select
        name="assignee"
        value={
          filter.assigneeId === undefined
            ? ""
            : (filter.assigneeId ?? UNASSIGNED_TOKEN)
        }
        options={assigneeOptions}
        onChange={(value) => onChange(withAssignee(filter, value))}
      />

      <div className="flex flex-wrap gap-1">
        {ISSUE_STATUSES.map((status) => {
          const active = (filter.status ?? []).includes(status);
          return (
            <Button
              key={status}
              variant={active ? "primary" : "ghost"}
              size="sm"
              onClick={() => onChange(toggleStatus(filter, status))}
            >
              {humanizeStatus(status)}
            </Button>
          );
        })}
      </div>

      {activeFilterCount(filter) > 0 ? (
        <Button variant="ghost" size="sm" onClick={() => onChange({})}>
          Clear ({activeFilterCount(filter)})
        </Button>
      ) : null}
    </div>
  );
}

function stripQuery(filter: IssueFilter): IssueFilter {
  const { query: _query, ...rest } = filter;
  return rest;
}

function stripProject(filter: IssueFilter): IssueFilter {
  const { projectId: _projectId, ...rest } = filter;
  return rest;
}

function withAssignee(filter: IssueFilter, raw: string): IssueFilter {
  if (raw.length === 0) {
    const { assigneeId: _assigneeId, ...rest } = filter;
    return rest;
  }
  return {
    ...filter,
    assigneeId: raw === UNASSIGNED_TOKEN ? null : (raw as UserId),
  };
}

import type {
  AttachmentId,
  IsoTimestamp,
  IssueId,
  LabelId,
  ProjectId,
  SoftDeletable,
  TenantScoped,
  Timestamps,
  UserId,
} from "./common";

export type IssueStatus =
  | "backlog"
  | "todo"
  | "in_progress"
  | "in_review"
  | "done"
  | "canceled";

export const ISSUE_STATUSES: readonly IssueStatus[] = [
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
];

/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

export type IssuePriority = "none" | "low" | "medium" | "high" | "urgent";

export const ISSUE_PRIORITIES: readonly IssuePriority[] = [
  "none",
  "low",
  "medium",
  "high",
  "urgent",
];

export interface Issue extends Timestamps, TenantScoped, SoftDeletable {
  readonly id: IssueId;
  readonly projectId: ProjectId;
  readonly number: number;
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly authorId: UserId;
  readonly assigneeId: UserId | null;
  readonly parentId: IssueId | null;
  readonly estimate: number | null;
  readonly dueAt: IsoTimestamp | null;
  readonly startedAt: IsoTimestamp | null;
  readonly completedAt: IsoTimestamp | null;
  readonly labelIds: readonly LabelId[];
}

export interface IssueLabel extends TenantScoped {
  readonly id: LabelId;
  readonly name: string;
  readonly color: string;
  readonly description: string | null;
}

export interface IssueAttachment extends Timestamps, TenantScoped {
  readonly id: AttachmentId;
  readonly issueId: IssueId;
  readonly filename: string;
  readonly contentType: string;
  readonly sizeBytes: number;
  readonly uploadedBy: UserId;
}

/** Filter accepted by the issue repository, service layer and list UI alike. */
export interface IssueFilter {
  readonly projectId?: ProjectId;
  readonly status?: readonly IssueStatus[];
  readonly priority?: readonly IssuePriority[];
  readonly assigneeId?: UserId | null;
  readonly authorId?: UserId;
  readonly labelIds?: readonly LabelId[];
  readonly query?: string;
  readonly dueBefore?: IsoTimestamp;
  readonly includeArchived?: boolean;
}

export interface IssueWithRelations {
  readonly issue: Issue;
  readonly labels: readonly IssueLabel[];
  readonly commentCount: number;
  readonly attachmentCount: number;
}

/** One column of the kanban board; the board is an ordered list of these. */
export interface IssueBoardColumn {
  readonly status: IssueStatus;
  readonly issues: readonly Issue[];
  readonly total: number;
}

/**
 * Timestamp helpers: ISO round-tripping, relative formatting, due-date and
 * digest-window arithmetic.
 *
 * Every timestamp in Taskflow is an `IsoTimestamp` (a UTC ISO-8601 string in
 * a SQLite text column). Nothing outside this module constructs a `Date` from
 * a stored value — going through `parseIso()` keeps the "what if it is
 * malformed" answer in one place.
 */
import type { IsoTimestamp } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;
const WEEK_MS = 7 * DAY_MS;

export function now(): IsoTimestamp {
  return toIsoTimestamp(new Date());
}

/** Parses a stored timestamp; throws rather than yielding an Invalid Date. */
export function parseIso(value: IsoTimestamp): Date {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Malformed IsoTimestamp: "${value}"`);
  }
  return date;
}

function plural(count: number, unit: string): string {
  return `${count} ${unit}${count === 1 ? "" : "s"}`;
}

/**
 * "just now" / "5 minutes ago" / "in 2 days" — the wording the activity feed,
 * issue cards and comment headers all use.
 */
export function formatRelative(
  value: IsoTimestamp,
  reference: Date = new Date(),
): string {
  const deltaMs = parseIso(value).getTime() - reference.getTime();
  const past = deltaMs < 0;
  const abs = Math.abs(deltaMs);

  const phrase = ((): string => {
    if (abs < MINUTE_MS) return "just now";
    if (abs < HOUR_MS) return plural(Math.floor(abs / MINUTE_MS), "minute");
    if (abs < DAY_MS) return plural(Math.floor(abs / HOUR_MS), "hour");
    if (abs < WEEK_MS) return plural(Math.floor(abs / DAY_MS), "day");
    if (abs < 30 * DAY_MS) return plural(Math.floor(abs / WEEK_MS), "week");
    if (abs < 365 * DAY_MS) return plural(Math.floor(abs / (30 * DAY_MS)), "month");
    return plural(Math.floor(abs / (365 * DAY_MS)), "year");
  })();

  if (phrase === "just now") return phrase;
  return past ? `${phrase} ago` : `in ${phrase}`;
}

/** Absolute calendar rendering, e.g. "12 Mar 2026", in the given timezone. */
export function formatDate(value: IsoTimestamp, timezone = "UTC"): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: timezone,
  }).format(parseIso(value));
}

/** True when a due date exists and has already passed. */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
): boolean {
  if (dueAt === null) return false;
  return parseIso(dueAt).getTime() < reference.getTime();
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The 24-hour window a digest covers, ending at today's `digestHourUtc`. If
 * that hour has not arrived yet on `reference`'s day, the window is the one
 * that ended yesterday — so a job run early never mails an empty digest and
 * then skips the real one.
 */
export function digestWindow(
  digestHourUtc: number,
  reference: Date,
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHourUtc) || digestHourUtc < 0 || digestHourUtc > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHourUtc}`);
  }

  const end = new Date(
    Date.UTC(
      reference.getUTCFullYear(),
      reference.getUTCMonth(),
      reference.getUTCDate(),
      digestHourUtc,
      0,
      0,
      0,
    ),
  );
  if (end.getTime() > reference.getTime()) {
    end.setUTCDate(end.getUTCDate() - 1);
  }

  return {
    start: toIsoTimestamp(new Date(end.getTime() - DAY_MS)),
    end: toIsoTimestamp(end),
  };
}

import { z } from "zod";
import { orgIdSchema, projectIdSchema } from "./common";
import { issuePrioritySchema, issueStatusSchema } from "./issue";

/** Query parameters accepted by `/api/export/issues`. Gated on the
 *  `csv_export` feature flag and on `activity:export` for the audit log. */
export const exportIssuesSchema = z.object({
  orgId: orgIdSchema,
  projectId: projectIdSchema.optional(),
  status: z.array(issueStatusSchema).optional(),
  priority: z.array(issuePrioritySchema).optional(),
  includeArchived: z.coerce.boolean().default(false),
  format: z.enum(["csv", "json"]).default("csv"),
});

export const exportColumnSchema = z.enum([
  "key",
  "title",
  "status",
  "priority",
  "assignee",
  "author",
  "dueAt",
  "createdAt",
  "updatedAt",
]);

export const DEFAULT_EXPORT_COLUMNS: readonly z.infer<
  typeof exportColumnSchema
>[] = ["key", "title", "status", "priority", "assignee", "dueAt"];

export type ExportIssuesInput = z.infer<typeof exportIssuesSchema>;
export type ExportColumn = z.infer<typeof exportColumnSchema>;

/**
 * Virtualised issue list; hides row actions the actor may not perform.
 *
 * Must call (do not reimplement): can
 */
import { EmptyState } from "@/components/ui/empty-state";
import {
  Table,
  TableBody,
  TableHead,
  TableHeaderCell,
  TableRow,
} from "@/components/ui/table";
import { can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import type { IssueId } from "@/types/common";
import type { IssueWithRelations } from "@/types/issue";
import type { Actor, User } from "@/types/member";
import type { ReactElement } from "react";
import { organizationResource } from "../permission/resources";
import { IssueRow } from "./issue-row";

export type IssueListProps = {
  issues: readonly IssueWithRelations[];
  actor: Actor;
  emptyLabel?: string;
  onArchive?: (issueId: IssueId) => void;
  /** Assignee lookup for the rows; the page joins users once, not per row. */
  users?: Readonly<Record<string, User>>;
};

const COLUMNS: readonly string[] = [
  "#",
  "Title",
  "Status",
  "Priority",
  "Assignee",
  "Due",
  "",
];

export function IssueList(props: IssueListProps): ReactElement | null {
  const { issues, actor, emptyLabel, onArchive, users = {} } = props;

  // One coarse check for the whole list: an actor who cannot read issues at
  // all sees the empty state rather than a table of hidden rows.
  if (!can(actor, "issue:read", organizationResource(actor.orgId))) {
    return (
      <EmptyState
        title="No access"
        description="Your role does not include issue access in this organization."
      />
    );
  }

  if (issues.length === 0) {
    return (
      <EmptyState
        title={emptyLabel ?? "No issues match this filter"}
        description="Adjust the filters or create the first issue."
      />
    );
  }

  // Live rows first; archived ones stay visible but sink to the bottom.
  const ordered = [...issues].sort((a, b) => {
    const archivedDelta =
      Number(isArchived(a.issue)) - Number(isArchived(b.issue));
    if (archivedDelta !== 0) return archivedDelta;
    return b.issue.updatedAt.localeCompare(a.issue.updatedAt);
  });

  return (
    <Table caption="Issues">
      <TableHead>
        <TableRow>
          {COLUMNS.map((column, index) => (
            <TableHeaderCell key={column.length === 0 ? `col-${index}` : column}>
              {column}
            </TableHeaderCell>
          ))}
        </TableRow>
      </TableHead>
      <TableBody>
        {ordered.map(({ issue }) => (
          <IssueRow
            key={issue.id}
            issue={issue}
            actor={actor}
            assignee={
              issue.assigneeId === null ? null : users[issue.assigneeId] ?? null
            }
            {...(onArchive !== undefined ? { onArchive } : {})}
          />
        ))}
      </TableBody>
    </Table>
  );
}

import { z } from "zod";
import type {
  ActivityId,
  AttachmentId,
  CommentId,
  InvitationId,
  IsoTimestamp,
  IssueId,
  LabelId,
  MemberId,
  NotificationId,
  OrgId,
  ProjectId,
  SubscriptionId,
