const RECENT_ISSUE_LIMIT = 8;
const PROJECT_LIMIT = 6;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const mayReadBilling = can(actor, "org:manage_billing", {
    kind: "billing",
    orgId: org.id,
  });

  const [issues, projects, billing] = await Promise.all([
    listIssues(actor, {
      orgId: org.id,
      assigneeId: actor.userId,
      status: ["todo", "in_progress", "in_review"],
      limit: RECENT_ISSUE_LIMIT,
    }),
    listProjects(actor, { orgId: org.id, limit: PROJECT_LIMIT }),
    mayReadBilling
      ? getBillingSummary(actor, org.id)
      : Promise.resolve<BillingSummary | null>(null),
  ]);

  return (
    <div className="space-y-12">
      <header>
        <h1 className="text-2xl font-semibold tracking-tight">{org.name}</h1>
        <p className="mt-1 text-sm text-slate-600">
          {projects.total} projects · {issues.total} issues assigned to you
        </p>
      </header>

      <section>
        <div className="mb-4 flex items-baseline justify-between">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
            Assigned to you
          </h2>
          <Link href={`/${orgSlug}/issues`} className="text-sm text-indigo-600">
            All issues
          </Link>
        </div>

        {issues.items.length === 0 ? (
          <EmptyState
            title="Nothing on your plate"
            description="Issues assigned to you show up here as soon as somebody picks you."
          />
        ) : (
          <ul className="space-y-2">
            {issues.items.map((issue) => (
              <li key={issue.id}>
                <IssueCard
                  issue={issue}
                  href={`/${orgSlug}/issues?issue=${issue.id}`}
                  compact
                />
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <div className="mb-4 flex items-baseline justify-between">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
            Projects
          </h2>
          <Link href={`/${orgSlug}/projects`} className="text-sm text-indigo-600">
            All projects
          </Link>
        </div>

        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {projects.items.map((row) => (
            <ProjectCard
              key={row.project.id}
              project={row.project}
              stats={row.stats}
              href={`/${orgSlug}/projects/${row.project.slug}`}
              actor={actor}
            />
          ))}
        </div>
      </section>

      {billing !== null ? (
        <section>
          <h2 className="mb-4 text-sm font-semibold uppercase tracking-wide text-slate-500">
            Usage
          </h2>
          <UsagePanel summary={billing} />
        </section>
      ) : null}
    </div>
  );
}

/**
 * Fetch/patch one issue over JSON.
 *
 * Owner D. The tenant check is explicit here rather than implied: the route
 * takes an `issueId` straight off the URL, so `assertOrgScope()` against the
 * fetched row is what stops one organization reading another's issue by id.
 *
 * Must call (do not reimplement): can, assertOrgScope
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { can } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { issueIdSchema } from "@/schemas/common";
import { updateIssueSchema } from "@/schemas/issue";
import { getIssue, updateIssue } from "@/server/services/issue-service";

export const dynamic = "force-dynamic";

type RouteContext = { params: Promise<{ issueId: string }> };

export async function GET(
  request: Request,
  context: RouteContext,
): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    // Next.js 16: route `params` is a Promise and MUST be awaited.
    const { issueId } = await context.params;
    const parsedId = issueIdSchema.safeParse(issueId);
    if (!parsedId.success) {
      return failure("validation_failed", "Malformed issue id.");
    }

    const actor = await getActor(orgSlug);
    const found = await getIssue(actor, actor.orgId, parsedId.data);
    assertOrgScope(actor, found.issue.orgId);

    const allowed = can(actor, "issue:read", {
      kind: "issue",
      orgId: found.issue.orgId,
      projectId: found.issue.projectId,
      issueId: found.issue.id,
      authorId: found.issue.authorId,
      assigneeId: found.issue.assigneeId,
    });
    if (!allowed) {
      return failure("forbidden", "You cannot read this issue.");
    }

    return Response.json(found);
  } catch (error) {
    return errorResponse(error);
  }
}

export async function PATCH(
  request: Request,
  context: RouteContext,
): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    // Next.js 16: route `params` is a Promise and MUST be awaited.
    const { issueId } = await context.params;
    const actor = await getActor(orgSlug);

    const body: unknown = await request.json();
    const parsed = updateIssueSchema.safeParse({
      ...(typeof body === "object" && body !== null ? body : {}),
      orgId: actor.orgId,
      issueId,
    });
    if (!parsed.success) {
      return failure("validation_failed", "Bad issue patch.");
    }

    const current = await getIssue(actor, actor.orgId, parsed.data.issueId);
    assertOrgScope(actor, current.issue.orgId);

    const allowed = can(actor, "issue:update", {
      kind: "issue",
      orgId: current.issue.orgId,
      projectId: current.issue.projectId,
      issueId: current.issue.id,
      authorId: current.issue.authorId,
      assigneeId: current.issue.assigneeId,
    });
    if (!allowed) {
      return failure("forbidden", "You cannot update this issue.");
    }

    const updated = await updateIssue(actor, parsed.data);
    return Response.json(updated);
  } catch (error) {
    return errorResponse(error);
  }
}

import { z } from "zod";

/**
 * Coercions for reading pagination out of `searchParams`. Remember that in
 * Next 16 `searchParams` is a Promise — `await` it before parsing.
 */
export const searchParamsPaginationSchema = z.object({
  page: z.coerce.number().int().min(1).catch(1),
  perPage: z.coerce.number().int().min(1).max(100).catch(25),
  cursor: z.string().optional(),
});

export const searchParamsSortSchema = z.object({
  sort: z.string().max(40).optional(),
  dir: z.enum(["asc", "desc"]).catch("desc"),
});

export function toOffset(page: number, perPage: number): number {
  return (page - 1) * perPage;
}

export type SearchParamsPagination = z.infer<
  typeof searchParamsPaginationSchema
>;
export type SearchParamsSort = z.infer<typeof searchParamsSortSchema>;

