export type IssueFilterBarProps = {
  filter: IssueFilter;
  projects: readonly Project[];
  members: readonly MemberWithUser[];
  onChange: (filter: IssueFilter) => void;
};

/** Adds or removes one status without disturbing the other dimensions. */
export function toggleStatus(
  filter: IssueFilter,
  status: IssueStatus,
): IssueFilter {
  const current = filter.status ?? [];
  const next = current.includes(status)
    ? current.filter((value) => value !== status)
    : [...current, status];
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

export function IssueFilterBar(
  props: IssueFilterBarProps,
): ReactElement | null {
  const { filter, projects, members, onChange } = props;

  const projectOptions: readonly SelectOption[] = [
    { value: "", label: "All projects" },
    ...projects.map((project) => ({
      value: project.id,
      label: project.name,
    })),
  ];

  const assigneeOptions: readonly SelectOption[] = [
    { value: "", label: "Anyone" },
    { value: UNASSIGNED_TOKEN, label: "Unassigned" },
    ...members.map((member) => ({
      value: member.userId,
      label: member.user.name,
    })),
  ];

  return (
    <div className="flex flex-wrap items-center gap-2">
      <Input
        name="q"
        type="search"
        value={filter.query ?? ""}
        placeholder="Search issues"
        onChange={(value) =>
          onChange(value.length === 0 ? stripQuery(filter) : { ...filter, query: value })
        }
      />

      <Select
        name="project"
        value={filter.projectId ?? ""}
        options={projectOptions}
        onChange={(value) =>
          onChange(
            value.length === 0
              ? stripProject(filter)
              : { ...filter, projectId: value as ProjectId },
          )
        }
      />

      <Select
        name="assignee"
        value={
          filter.assigneeId === undefined
            ? ""
            : (filter.assigneeId ?? UNASSIGNED_TOKEN)
        }
        options={assigneeOptions}
        onChange={(value) => onChange(withAssignee(filter, value))}
      />

      <div className="flex flex-wrap gap-1">
        {ISSUE_STATUSES.map((status) => {
          const active = (filter.status ?? []).includes(status);
          return (
            <Button
              key={status}
              variant={active ? "primary" : "ghost"}
              size="sm"
              onClick={() => onChange(toggleStatus(filter, status))}
            >
              {humanizeStatus(status)}
            </Button>
          );
        })}
      </div>

      {activeFilterCount(filter) > 0 ? (
        <Button variant="ghost" size="sm" onClick={() => onChange({})}>
          Clear ({activeFilterCount(filter)})
        </Button>
      ) : null}
    </div>
  );
}

function stripQuery(filter: IssueFilter): IssueFilter {
  const { query: _query, ...rest } = filter;
  return rest;
}

function stripProject(filter: IssueFilter): IssueFilter {
  const { projectId: _projectId, ...rest } = filter;
  return rest;
}

function withAssignee(filter: IssueFilter, raw: string): IssueFilter {
  if (raw.length === 0) {
    const { assigneeId: _assigneeId, ...rest } = filter;
    return rest;
  }
  return {
    ...filter,
    assigneeId: raw === UNASSIGNED_TOKEN ? null : (raw as UserId),
  };
}

"use server";

/**
 * Creates an issue after the per-project quota check.
 *
 * Owner D. The quota is read from `@/config/plan-limits` rather than hard-coded
 * here — the plan of the owning organization decides `issuesPerProject`.
 *
 * Must call (do not reimplement): createIssueSchema, can, getPlanLimits,
 * getActor, toActionResult
 */

import { withAction } from "@/actions/_lib/with-action";
import { ForbiddenActionError, PlanLimitError } from "@/actions/_lib/action-errors";
import { getPlanLimits } from "@/config/plan-limits";
import { issueTag, orgTag, projectTag, revalidateTagged, CACHE_PROFILES } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { createIssueSchema, type CreateIssueInput } from "@/schemas/issue";
import { createIssue, listIssues } from "@/server/services/issue-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";

const run = withAction<typeof createIssueSchema, Issue>(
  createIssueSchema,
  async (raw, actor) => {
    const input = raw as CreateIssueInput;

    const allowed = can(actor, "issue:create", {
      kind: "issue",
      orgId: input.orgId,
      projectId: input.projectId,
      issueId: "" as Issue["id"],
      authorId: actor.userId,
      assigneeId: input.assigneeId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("issue:create");
    }

    await assertProjectHasRoom(actor, input);

    const issue = await createIssue(actor, input);

    revalidateTagged(
      [orgTag(input.orgId), projectTag(input.projectId), issueTag(issue.id)],
      CACHE_PROFILES.minutes,
    );
    return issue;
  },
  { revalidate: ["issues"], cacheProfile: "minutes" },
);

/**
 * Counts the issues already living in the project and compares them with the
 * plan's `issuesPerProject` ceiling. Archived issues still occupy the quota,
 * which is why the count deliberately includes them.
 */
async function assertProjectHasRoom(
  actor: Actor,
  input: CreateIssueInput,
): Promise<void> {
  const summary = await getOrganizationSummary(actor, input.orgId);
  const limits = getPlanLimits(summary.organization.plan);

  const existing = await listIssues(actor, {
    orgId: input.orgId,
    projectId: input.projectId,
    limit: 1,
    includeArchived: true,
  });

  if (existing.total >= limits.issuesPerProject) {
    throw new PlanLimitError("issuesPerProject", limits.issuesPerProject, existing.total);
  }
}

export async function createIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
  return run(raw);
}

