/** Cascade behind `ProjectService.archiveProject`; returns the row count. */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

/** Live, still-open issues whose due date has passed. Drives the overdue job. */
export async function listOverdueIssues(
  orgId: OrgId,
  now: IsoTimestamp,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          livePredicate(issues.archivedAt, {}),
          isNotNull(issues.dueAt),
          lt(issues.dueAt, now),
          inArray(issues.status, ["backlog", "todo", "in_progress", "in_review"]),
        ),
      ),
    )
    .orderBy(issues.dueAt)
    .all();

  return rows.map((row) => toIssue(row));
}

/**
 * Streams the issue CSV; requires the `csv_export` flag.
 *
 * Owner D. Query parameters are parsed with `exportIssuesSchema` — the same
 * schema the export UI submits — so `?includeArchived=true` cannot mean one
 * thing in the form and another here.
 *
 * Must call (do not reimplement): can, isEnabled, toCsv
 */

import { PENDING_ISSUE_ID, PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { csvResponseHeaders, toCsv } from "@/lib/csv";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { parseIssueFilterParams } from "@/hooks/issue-filter-params";
import { exportIssuesSchema } from "@/schemas/export";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { listIssues } from "@/server/services/issue-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { Issue } from "@/types/issue";

export const dynamic = "force-dynamic";

const EXPORT_PAGE_LIMIT = 100;

const COLUMNS: readonly string[] = [
  "number",
  "title",
  "status",
  "priority",
  "assigneeId",
  "authorId",
  "dueAt",
  "createdAt",
  "updatedAt",
];

export async function GET(request: Request): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    const actor = await getActor(orgSlug);
    const { organization } = await getOrganizationSummary(actor, actor.orgId);

    if (!isEnabled("csv_export", buildFlagContext(actor, organization))) {
      return failure("forbidden", "CSV export is not included in this plan.");
    }

    const allowed = can(actor, "issue:read", {
      kind: "issue",
      orgId: actor.orgId,
      projectId: PENDING_PROJECT_ID,
      issueId: PENDING_ISSUE_ID,
      authorId: actor.userId,
      assigneeId: actor.userId,
    });
    if (!allowed) {
      return failure("forbidden", "You cannot export issues in this organization.");
    }

    const parsed = exportIssuesSchema.safeParse({
      ...parseIssueFilterParams(url.searchParams),
      orgId: actor.orgId,
      format: url.searchParams.get("format") ?? "csv",
    });
    if (!parsed.success) {
      return failure("validation_failed", "Bad export parameters.");
    }

    const { format, ...filter } = parsed.data;
    const page = await listIssues(actor, {
      ...filter,
      limit: EXPORT_PAGE_LIMIT,
    });

    if (format === "json") {
      return Response.json({ items: page.items, total: page.total });
    }

    const csv = toCsv(page.items.map(toRow), COLUMNS);
    return new Response(csv, {
      headers: csvResponseHeaders(`taskflow-issues-${organization.slug}.csv`),
    });
  } catch (error) {
    return errorResponse(error);
  }
}

/** Flattens an `Issue` into the scalar row shape `toCsv` accepts. */
function toRow(issue: Issue): Record<string, string | number | boolean | null> {
  return {
    number: issue.number,
    title: issue.title,
    status: issue.status,
    priority: issue.priority,
    assigneeId: issue.assigneeId,
    authorId: issue.authorId,
    dueAt: issue.dueAt,
    createdAt: issue.createdAt,
    updatedAt: issue.updatedAt,
  };
}

/**
 * Project issue list; parses filters from `await searchParams`.
 *
 * Owner D. The filter is rebuilt from the URL on every render rather than kept
 * in component state, so a filtered list is a shareable link.
 *
 * Must call (do not reimplement): can
 */

import Link from "next/link";
import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { PENDING_ISSUE_ID } from "@/actions/_lib/permission-resources";
import { IssueList } from "@/components/domain/issue/issue-list";
import { IssueFilterControls } from "@/components/domain/issue/issue-filter-controls";
import { EmptyState } from "@/components/ui/empty-state";
import { can } from "@/lib/permissions";
import { issueFilterSchema } from "@/schemas/issue";
import { searchParamsPaginationSchema } from "@/schemas/pagination";
import {
  parseIssueFilterParams,
  readableParamsFromRecord,
} from "@/hooks/issue-filter-params";
import { getIssue, listIssues } from "@/server/services/issue-service";
import { listLabels } from "@/server/services/label-service";
import { listMembers } from "@/server/services/member-service";
import type { IssueWithRelations } from "@/types/issue";
import { loadProjectContext } from "../../../_lib/project-context";

type PageParams = { orgSlug: string; projectSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Issues",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug, projectSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor, project } = await loadProjectContext(orgSlug, projectSlug);

  const mayRead = can(actor, "issue:read", {
    kind: "issue",
    orgId: org.id,
    projectId: project.id,
    issueId: PENDING_ISSUE_ID,
    authorId: actor.userId,
    assigneeId: actor.userId,
  });
  if (!mayRead) {
    notFound();
  }

  const mayCreate = can(actor, "issue:create", {
    kind: "issue",
    orgId: org.id,
    projectId: project.id,
    issueId: PENDING_ISSUE_ID,
    authorId: actor.userId,
    assigneeId: null,
  });

  const [labels, members] = await Promise.all([
    listLabels(actor, org.id),
    can(actor, "member:read", { kind: "organization", orgId: org.id })
      ? listMembers(actor, { orgId: org.id, limit: 100 }).then((page) => page.items)
      : Promise.resolve([]),
  ]);

  const pagination = searchParamsPaginationSchema.parse(search);
  const urlFilter = parseIssueFilterParams(readableParamsFromRecord(search));

  // The filter goes through the shared schema so an unparseable URL is a
  // rejected filter rather than a malformed repository query.
  const filter = issueFilterSchema.parse({
    ...urlFilter,
    orgId: org.id,
    projectId: project.id,
    limit: pagination.perPage,
    cursor: pagination.cursor ?? null,
  });

  const page = await listIssues(actor, filter);
  const rows: IssueWithRelations[] = await Promise.all(
    page.items.map((issue) => getIssue(actor, org.id, issue.id)),
  );

  return (
    <div className="space-y-6">
      <IssueFilterControls
        projects={[project]}
        members={members}
        labels={labels}
        showProjectFilter={false}
      />
      <div className="flex items-baseline justify-between">
        <p className="text-sm text-slate-600">
          {page.total} issues in {project.name}
        </p>
        {mayCreate ? (
          <Link
            href={`/${orgSlug}/projects/${projectSlug}/issues/new`}
            className="rounded-md bg-indigo-600 px-3 py-1.5 text-sm font-medium text-white"
          >
            New issue
          </Link>
        ) : null}
      </div>

      {rows.length === 0 ? (
        <EmptyState
          title="No issues match this filter"
          description="Clear the filter, or file the first issue in this project."
        />
      ) : (
        <IssueList issues={rows} actor={actor} />
      )}
    </div>
  );
}

import { z } from "zod";
import { issueFilterSchema } from "./issue";

/** Export requests use the same filter vocabulary and validation as issue lists. */
export const exportIssuesSchema = issueFilterSchema
  .omit({ limit: true, cursor: true })
  .extend({ format: z.enum(["csv", "json"]).default("csv") });

export const exportColumnSchema = z.enum([
  "key",
  "title",
  "status",
  "priority",
  "assignee",
  "author",
  "dueAt",
  "createdAt",
  "updatedAt",
]);

export const DEFAULT_EXPORT_COLUMNS: readonly z.infer<
  typeof exportColumnSchema
>[] = ["key", "title", "status", "priority", "assignee", "dueAt"];

export type ExportIssuesInput = z.infer<typeof exportIssuesSchema>;
export type ExportColumn = z.infer<typeof exportColumnSchema>;

/**
 * The URL is the shared issue-filter vocabulary. Pages, client controls and
 * request handlers use this codec before the filter schema validates values.
 */
import type {
  CalendarDate,
  IsoTimestamp,
  LabelId,
  ProjectId,
  UserId,
} from "@/types/common";
import {
  CLOSED_ISSUE_STATUSES,
  ISSUE_PRIORITIES,
  ISSUE_STATUSES,
  OPEN_ISSUE_STATUSES,
  type IssueFilter,
  type IssuePriority,
  type IssueStatus,
} from "@/types/issue";

export const UNASSIGNED_TOKEN = "none";

export interface ReadableParams {
  get(name: string): string | null;
}

export type SearchParamsRecord = Record<string, string | string[] | undefined>;

/** Adapts Next's plain searchParams object to the browser URLSearchParams API. */
export function readableParamsFromRecord(
  search: SearchParamsRecord,
): ReadableParams {
  const values = new Map<string, string>();
  for (const [key, value] of Object.entries(search)) {
    if (value === undefined) continue;
    values.set(key, Array.isArray(value) ? value.join(",") : value);
  }
  return { get: (name) => values.get(name) ?? null };
}

function splitList(raw: string | null): readonly string[] {
  if (raw === null || raw.length === 0) return [];
  return [...new Set(raw.split(",").map((part) => part.trim()).filter(Boolean))];
}

function expandStatuses(values: readonly string[]): readonly IssueStatus[] {
  const expanded = new Set<IssueStatus>();
  for (const value of values) {
    if (value === "open") {
      OPEN_ISSUE_STATUSES.forEach((status) => expanded.add(status));
    } else if (value === "closed") {
      CLOSED_ISSUE_STATUSES.forEach((status) => expanded.add(status));
    } else if ((ISSUE_STATUSES as readonly string[]).includes(value)) {
      expanded.add(value as IssueStatus);
    }
  }
  return ISSUE_STATUSES.filter((status) => expanded.has(status));
}

export function parseIssueFilterParams(params: ReadableParams): IssueFilter {
  const statuses = expandStatuses(splitList(params.get("status")));
  const priorities = splitList(params.get("priority")).filter(
    (value): value is IssuePriority =>
      ISSUE_PRIORITIES.includes(value as IssuePriority),
  );
  const labelIds = splitList(params.get("label")) as readonly LabelId[];
  const project = params.get("project");
  const rawAssignee = params.get("assignee");
  const rawAuthor = params.get("author");
  const query = params.get("q");
  const dueBefore = params.get("due_before");
  const archived = params.get("archived");

  const filter: IssueFilter = {
    ...(project ? { projectId: project as ProjectId } : {}),
    ...(statuses.length > 0 ? { status: statuses } : {}),
    ...(priorities.length > 0 ? { priority: priorities } : {}),
    ...(rawAssignee
      ? {
          assigneeId:
            rawAssignee === UNASSIGNED_TOKEN
              ? null
              : rawAssignee === "me"
                ? "me"
                : (rawAssignee as UserId),
        }
      : {}),
    ...(rawAuthor
      ? { authorId: rawAuthor === "me" ? "me" : (rawAuthor as UserId) }
      : {}),
    ...(labelIds.length > 0 ? { labelIds } : {}),
    ...(query ? { query } : {}),
    ...(dueBefore
      ? { dueBefore: dueBefore as CalendarDate | IsoTimestamp }
      : {}),
    ...(archived === "1" ? { archiveScope: "include" as const } : {}),
    ...(archived === "only" ? { archiveScope: "only" as const } : {}),
  };

  return filter;
}

function serialiseStatuses(statuses: readonly string[]): string {
  const selected = new Set<string>(statuses);
  if (selected.delete("open")) OPEN_ISSUE_STATUSES.forEach((status) => selected.add(status));
  if (selected.delete("closed")) CLOSED_ISSUE_STATUSES.forEach((status) => selected.add(status));
  const values: string[] = [];
  if (OPEN_ISSUE_STATUSES.every((status) => selected.has(status))) {
    values.push("open");
    OPEN_ISSUE_STATUSES.forEach((status) => selected.delete(status));
  }
  if (CLOSED_ISSUE_STATUSES.every((status) => selected.has(status))) {
    values.push("closed");
    CLOSED_ISSUE_STATUSES.forEach((status) => selected.delete(status));
  }
  for (const status of ISSUE_STATUSES) {
    if (selected.has(status)) values.push(status);
  }
  return values.join(",");
}

/** Inverse of parseIssueFilterParams; empty dimensions have no URL spelling. */
export function issueFilterToParams(
  filter: IssueFilter,
): Readonly<Record<string, string>> {
  const params: Record<string, string> = {};
  if (filter.projectId !== undefined) params.project = filter.projectId;
  if (filter.status !== undefined && filter.status.length > 0) {
    params.status = serialiseStatuses(filter.status);
  }
  if (filter.priority !== undefined && filter.priority.length > 0) {
    params.priority = filter.priority.join(",");
  }
  if (filter.assigneeId !== undefined) {
    params.assignee =
      filter.assigneeId === null ? UNASSIGNED_TOKEN : filter.assigneeId;
  }
  if (filter.authorId !== undefined) params.author = filter.authorId;
  if (filter.labelIds !== undefined && filter.labelIds.length > 0) {
    params.label = [...new Set(filter.labelIds)].join(",");
  }
  if (filter.query !== undefined && filter.query.length > 0) {
    params.q = filter.query;
  }
  if (filter.dueBefore !== undefined) params.due_before = filter.dueBefore;
  if (filter.archiveScope === "only") {
    params.archived = "only";
  } else if (filter.archiveScope === "include" || filter.includeArchived === true) {
    params.archived = "1";
  }
  return params;
}

/** How many dimensions the user has narrowed on, for the clear affordance. */
export function activeFilterCount(filter: IssueFilter): number {
  return Object.keys(issueFilterToParams(filter)).length;
}

export function issueFilterQueryString(filter: IssueFilter): string {
  const search = new URLSearchParams(issueFilterToParams(filter));
  const serialised = search.toString();
  return serialised.length > 0 ? "?" + serialised : "";
}

