export type IssueFilterBarProps = {
  filter: IssueFilter;
  projects: readonly Project[];
  members: readonly MemberWithUser[];
  labels?: readonly IssueLabel[];
  showProjectFilter?: boolean;
  showAssigneeFilter?: boolean;
  onChange: (filter: IssueFilter) => void;
};

/** Adds or removes one status without disturbing the other dimensions. */
export function toggleStatus(
  filter: IssueFilter,
  status: IssueStatus,
): IssueFilter {
  const current = concreteStatuses(filter.status ?? []);
  const next = current.includes(status)
    ? current.filter((value) => value !== status)
    : [...current, status];
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

export function toggleStatusGroup(
  filter: IssueFilter,
  group: "open" | "closed",
): IssueFilter {
  const members = group === "open" ? OPEN_ISSUE_STATUSES : CLOSED_ISSUE_STATUSES;
  const current = concreteStatuses(filter.status ?? []);
  const active = members.every((status) => current.includes(status));
  const next = active
    ? current.filter((status) => !members.includes(status))
    : [...new Set([...current, ...members])];
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

function concreteStatuses(
  statuses: readonly (IssueStatus | "open" | "closed")[],
): IssueStatus[] {
  const result = new Set<IssueStatus>();
  statuses.forEach((status) => {
    if (status === "open") OPEN_ISSUE_STATUSES.forEach((member) => result.add(member));
    else if (status === "closed") CLOSED_ISSUE_STATUSES.forEach((member) => result.add(member));
    else result.add(status);
  });
  return ISSUE_STATUSES.filter((status) => result.has(status));
}

function togglePriority(filter: IssueFilter, priority: IssuePriority): IssueFilter {
  const current = filter.priority ?? [];
  const next = current.includes(priority)
    ? current.filter((value) => value !== priority)
    : [...current, priority];
  const { priority: _dropped, ...rest } = filter;
