/** Adds or removes one status without disturbing the other dimensions. */
export function toggleStatus(
  filter: IssueFilter,
  status: IssueStatus,
): IssueFilter {
  const current = concreteStatuses(filter.status ?? []);
  const next = current.includes(status)
    ? current.filter((value) => value !== status)
    : [...current, status];
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

export function toggleStatusGroup(
  filter: IssueFilter,
  group: "open" | "closed",
): IssueFilter {
  const members = group === "open" ? OPEN_ISSUE_STATUSES : CLOSED_ISSUE_STATUSES;
  const current = concreteStatuses(filter.status ?? []);
  const active = members.every((status) => current.includes(status));
  const next = active
    ? current.filter((status) => !members.includes(status))
    : [...new Set([...current, ...members])];
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

function concreteStatuses(
  statuses: readonly (IssueStatus | "open" | "closed")[],
): IssueStatus[] {
  const result = new Set<IssueStatus>();
  statuses.forEach((status) => {
    if (status === "open") OPEN_ISSUE_STATUSES.forEach((member) => result.add(member));
    else if (status === "closed") CLOSED_ISSUE_STATUSES.forEach((member) => result.add(member));
    else result.add(status);
  });
  return ISSUE_STATUSES.filter((status) => result.has(status));
}

"use client";

/**
 * Reads and writes the issue filter through the URL search params.
 */
import { useCallback, useMemo } from "react";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import type { IssueFilter } from "@/types/issue";
import {
  issueFilterQueryString,
  parseIssueFilterParams,
} from "./issue-filter-params";

const EMPTY_FILTER: IssueFilter = {};

export function useIssueFilters(defaults: IssueFilter = EMPTY_FILTER): {
  filter: IssueFilter;
  setFilter: (filter: IssueFilter) => void;
  reset: () => void;
} {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const filter = useMemo(
    () => ({ ...defaults, ...parseIssueFilterParams(searchParams) }),
    [searchParams, defaults],
  );

  const setFilter = useCallback(
    (next: IssueFilter) => {
      // Changing a filter always returns to page 1; keeping the old cursor
      // would show an empty page for a narrower result set.
      router.replace(`${pathname}${issueFilterQueryString(next)}`, {
        scroll: false,
      });
    },
    [router, pathname],
  );

  const reset = useCallback(() => {
    router.replace(pathname, { scroll: false });
  }, [router, pathname]);

  return { filter, setFilter, reset };
}

}

